8	/// Driver configuration for the Temporal runtime.
9	#[derive(Debug, Clone, Serialize, Deserialize)]
10	pub struct DriverConfig {
11	    /// Maximum number of turns the agent may execute before hitting the budget.
12	    pub max_turns: u32,
13	    /// Limit on concurrent tool calls; None = no limit.
14	    pub parallel_tool_call_limit: Option<usize>,
15	}
16	
17	/// Input envelope for the Temporal workflow.
18	///
19	/// Seeds the durable run with the agent name, conversation history,
20	/// configuration, and timeout.
21	#[derive(Debug, Clone, Serialize, Deserialize)]
22	pub struct WorkflowInput {
23	    /// Agent name to invoke.
24	    pub agent_name: String,
25	    /// Session snapshot plus new-turn messages.
26	    ///
27	    /// The workflow seeds the system message from the render_instructions
28	    /// activity result; this field contains user messages and prior turn
29	    /// items but NOT a system item.
30	    pub conversation: Vec<Item>,
31	    /// Runtime configuration (turn budget, tool call limits).
32	    pub config: DriverConfig,
33	    /// Run timeout as milliseconds; None = no deadline.
34	    pub timeout_ms: Option<u64>,
35	    /// Optional, explicit request-scoped seed the worker's seeded ctx factory
36	    /// reconstitutes into a `Ctx`. `#[serde(default)]` so pre-SMA-455 payloads
37	    /// (which lack the field) still deserialize. Recorded in Temporal history —
38	    /// keep it small and secret-free.
39	    #[serde(default)]
40	    pub ctx_seed: Option<serde_json::Value>,
41	}
