43	/// A reassembled model turn, wrapped for Temporal serialization.
44	#[derive(Debug, Clone, Serialize, Deserialize)]
45	pub struct ModelTurnResult(
46	    /// The underlying [`ModelTurn`] produced by the model.
47	    pub ModelTurn,
48	);
