50	/// The final successful output of an agent run.
51	#[derive(Debug, Clone, Serialize, Deserialize)]
52	pub struct FinalOutputPayload {
53	    /// Content items the agent produced (text, tool calls, etc.).
54	    pub content: Vec<ContentPart>,
55	    /// Cumulative token usage for the run.
56	    pub usage: TokenUsage,
57	}
