59	/// The terminal status of a durable run.
60	#[derive(Debug, Clone, Serialize, Deserialize)]
61	pub enum RunStatusPayload {
62	    /// Run succeeded with a final output.
63	    Completed(FinalOutputPayload),
64	    /// Run failed with an agent error.
65	    AgentFailed(ErrorKindPayload),
66	    /// Run was externally cancelled.
67	    Cancelled,
68	    /// Run exceeded its timeout deadline.
69	    TimedOut,
70	}
71	
72	/// The complete outcome of a durable agent run.
73	///
74	/// Combines the terminal status, event stream history, and cumulative usage.
75	#[derive(Debug, Clone, Serialize, Deserialize)]
76	pub struct DurableRunOutcome {
77	    /// The terminal run status.
78	    pub status: RunStatusPayload,
79	    /// All agent events emitted during the run.
80	    pub events: Vec<AgentEvent>,
81	    /// Cumulative token usage across the entire run.
82	    pub usage: TokenUsage,
83	}
