fn is_unit_payloads(payloads: &[Payload]) -> bool {
    match payloads {
        [] => true,
        [payload] => {
            payload.data.is_empty()
                && payload
                    .metadata
                    .get("encoding")
                    .map(|encoding| encoding == b"binary/null")
                    .unwrap_or(false)
        }
        _ => false,
    }
}

